class TestChaosEngineering:
    """Simulate extreme conditions to verify robustness."""

    def test_very_large_dataset_performance(self, component_module):
        """Renders 10,000 data points within acceptable time."""
        import time
        large_data = [
            {"task_id": f"task-{i}", "latency_ms": random.randint(1, 10000), "timestamp": f"2026-07-31T{i//3600:02d}:{(i//60)%60:02d}:{i%60:02d}Z"}
            for i in range(10000)
        ]
        start = time.time()
        render(component_module.TaskLatencyChart, {"data": large_data})
        elapsed = time.time() - start
        assert elapsed < 2.0, f"Rendering took {elapsed:.2f}s, exceeds 2s budget"

    def test_rapid_re_render_stability(self, component_module, sample_latency_data):
        """Component remains stable across 100 rapid re-renders."""
        for i in range(100):
            render(component_module.TaskLatencyChart, {"data": sample_latency_data})
            # Force garbage collection to simulate memory pressure
            import gc
            gc.collect()
        assert True  # No crash

    def test_concurrent_instances(self, component_module, sample_latency_data):
        """Multiple chart instances render independently without state bleed."""
        render(component_module.TaskLatencyChart, {"data": sample_latency_data})
        render(component_module.TaskLatencyChart, {"data": []})
        render(component_module.TaskLatencyChart, {"data": sample_latency_data})
        # Each instance maintains its own state
        assert recharts_mock.get_instance_count() == 3


